"""Translations for everything the support bot says WITHOUT the model.

The AI's own replies are produced in the requested language by the system prompt.
These are the deterministic strings — greetings, the keyword fallback replies used when
the model is unavailable, and the ticket-raised confirmation — which must be translated
rather than generated so the bot never silently drops to English.

`LANGS` mirrors the frontend's LOCALE_CODES. English is the fallback for any gap.
"""

LANGS = ("en", "hi", "or", "bn", "gu", "ta", "te")

LANG_NAMES = {
    "en": "English",
    "hi": "Hindi (हिन्दी)",
    "or": "Odia (ଓଡ଼ିଆ)",
    "bn": "Bengali (বাংলা)",
    "gu": "Gujarati (ગુજરાતી)",
    "ta": "Tamil (தமிழ்)",
    "te": "Telugu (తెలుగు)",
}

# Script instruction handed to the model so it never transliterates into Latin script.
LANG_SCRIPTS = {
    "en": "English",
    "hi": "Hindi, written in the Devanagari script",
    "or": "Odia, written in the Odia script",
    "bn": "Bengali, written in the Bengali script",
    "gu": "Gujarati, written in the Gujarati script",
    "ta": "Tamil, written in the Tamil script",
    "te": "Telugu, written in the Telugu script",
}


def norm(lang: str | None) -> str:
    lang = (lang or "en").lower().strip()
    return lang if lang in LANGS else "en"


