def tr(table: dict, lang: str, *keys):
    """Look a value up in a {lang: ...} table, falling back to English."""
    node = table.get(norm(lang), table["en"])
    for k in keys:
        node = node.get(k) if isinstance(node, dict) else None
        if node is None:
            node = table["en"]
            for k2 in keys:
                node = node.get(k2) if isinstance(node, dict) else None
            break
    return node
